const age = 28;

const user = { name, age }; // shorthand for { name: name, age: age }
console.log(user); // { name: 'Ana', age: 28 }

const key = "color";
const car = { [key]: "red" };

console.log(car); // { color: 'red' }

const user = { "first name": "Ana", age: 28 };

console.log(user.age); // 28
console.log(user["first name"]); // "Ana"

const key = "age";
console.log(user[key]); // 28

const user = {};
Object.defineProperty(user, "id", {
  value: 1,
  writable: false,
  enumerable: true
});

user.id = 99; // ignored, because writable is false
console.log(user.id); // 1

const user = {
  name: "Ana",
  greet() {
    return `Hi, I'm ${this.name}`;
  }
};

console.log(user.greet()); // "Hi, I'm Ana"

const user = { name: "Ana", age: 28 };
delete user.age;

console.log(user); // { name: 'Ana' }
console.log("age" in user); // false

const user = { name: "Ana", age: 28 };
const updated = { ...user, age: 29 };

console.log(updated); // { name: 'Ana', age: 29 }
console.log(user); // { name: 'Ana', age: 28 }

const user = { name: "Ana", age: 28 };
console.log(user.hasOwnProperty("name")); // true
console.log(Object.entries(user)); // [ [ 'name', 'Ana' ], [ 'age', 28 ] ]

const frozen = Object.freeze({ count: 1 });
frozen.count = 99; // silently ignored outside strict mode

console.log(frozen.count); // 1

