assignment.solution:
function doubleValues(obj) {
  return Object.fromEntries(
    Object.entries(obj).map(([key, value]) => [key, value * 2])
  );
}

console.log(doubleValues({ a: 1, b: 2 })); // { a: 2, b: 4 }

