class Animal {
  constructor(name) {
    this.name = name;
  }
  get label() {
    return `Animal: ${this.name}`;
  }
}

class Dog extends Animal {
  bark() {
    return `${this.name} says woof`;
  }
}

const rex = new Dog("Rex");
console.log(rex.label); // "Animal: Rex"
console.log(rex.bark()); // "Rex says woof"
console.log(rex instanceof Animal); // true

